    (* LPS 727298f3: [rz_openat_absent]/[_dot]/[_file] take the path's end below [TASK_SIZE];
       from MainOpen's [path_facts] under [Hfit]. *)
    Lemma reg11_task : forall R : bvmap 5 word, getr R 11 = pp ->
      bv_unsigned (getr R 11) + Z.of_nat (length path) < TASK_SIZE.
    Proof.
      intros R H11.
      destruct (path_facts sp0 a0s path envv rdraw tid regs0 mem0 brk mbase lim fs0 stdin0 Hva Hve Hvsp Htid ME Hvl Hlau)
        as (_ & _ & _ & PF4 & _).
      pose proof (PF4 Hfit) as PFB. rewrite H11. unfold pp in *. unfold TASK_SIZE. lia.
    Qed.

