    Theorem ref_open_fail_toolong :
      (4096 <= length path)%nat ->
      realizes RSEGS (mkCfg (mkst regs0 (Z_to_bv 64 0x473d0) mem0 (seg_rom RSEGS)) model0)
               (t_die (msg_cannot_open path) fs0).
Proof.
