    Theorem ref_open_fail_empty :
      path = [] ->
      realizes RSEGS (mkCfg (mkst regs0 (Z_to_bv 64 0x473d0) mem0 (seg_rom RSEGS)) model0)
               (t_die (msg_cannot_open path) fs0).
    (* LPS 727298f3 port: written out.  [p1] now depends on the path's length (the argument
       strings sit below the stack top), so the recorded proof's conversion between
       [p1 .. a0s [] ..] and [p1 .. a0s path ..] no longer holds; the path fact is taken at [pp]
       and rewritten with [Hnil] only where [path] is visible.  Text of boost-beast/http_request's
       lib/MainTop.v [ref_open_fail_empty], with this tree's names and the [TASK_SIZE] premise
       [rz_openat_empty] gained (from MainOpen's [path_facts] under [Hfit]). *)
    Proof.
      intros Hnil. pose proof SPlo as Hlo. pose proof SPhi as Hhi.
      apply (seg_A sp0 a0s path envv rdraw tid regs0 mem0 brk mbase lim fs0 stdin0 Hva Hve Hvsp Htid ME Hvl Hlau).
      intros vals R M HL P0 P2 P5 HR HK FM FA.
      pose proof (statics_at_open M FM FA) as ST. pose proof (heap_at_open M FM) as RH. pose proof (above_at_open M FM) as ABOVE.
      destruct (openat_regs' sp0 a0s path envv rdraw tid regs0 mem0 brk mbase lim fs0 stdin0 Hva Hve Hvsp Htid ME Hvl Hlau
                  vals R P2 HR) as (H17 & H10 & H11 & Hfl).
      destruct (KRELh ps0 model0 KR0) as [Hh Hlazy].
      destruct (path_at_A sp0 a0s path envv rdraw tid regs0 mem0 brk mbase lim fs0 stdin0 Hva Hve Hvsp Htid ME Hvl Hlau
                  M FM ltac:(rewrite Hnil; cbn; lia)) as (PA1 & PA2 & PA3).
      destruct (path_facts sp0 a0s path envv rdraw tid regs0 mem0 brk mbase lim fs0 stdin0 Hva Hve Hvsp Htid ME Hvl Hlau)
        as (_ & _ & _ & PF4 & _).
      pose proof (PF4 Hfit) as PFB.
      eapply (rz_openat_empty RSEGS R _ M model0 ECALLW ECALL_ebf04 is_ecall_ECALLW Hh Hlazy H17 H10 Hfl).
      - split; [cbn; lia|]. split; [intros [] |]. rewrite H11.
        replace (length (@nil byte) + 1)%nat with (length path + 1)%nat by (rewrite Hnil; reflexivity).
        replace ([] ++ [Z_to_bv 8 0]) with (path ++ [Z_to_bv 8 0]) by (rewrite Hnil; reflexivity).
        exact PA3.
      - rewrite H11. unfold TASK_SIZE. lia.
      - lazymatch goal with |- realizes _ (mkCfg (mkst _ ?p _ _) _) _ =>
          replace p with (Z_to_bv 64 0xebe8c) by (apply bv_eq; reflexivity) end.
        exact (open_fail ENOENT vals R M ltac:(unfold ENOENT; lia) scF_ENOENT HL P0 P2 HR HK ST RH ABOVE).
    Qed.

    Theorem ref_open_fail_absent :
      (length path <= 4095)%nat -> path <> [] -> path_has_slash path = false -> path_is_dirref path = false ->
      fs_lookup fs0 path = None ->
      realizes RSEGS (mkCfg (mkst regs0 (Z_to_bv 64 0x473d0) mem0 (seg_rom RSEGS)) model0)
